import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"Module: eval","description":"","frontmatter":{},"headers":[],"relativePath":"api/host/handl_platform/eval.md","filePath":"api/host/handl_platform/eval.md"}`),a={name:`api/host/handl_platform/eval.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<p><strong>handl_platform &gt; eval</strong></p><h1 id="module-eval" tabindex="-1">Module: eval <a class="header-anchor" href="#module-eval" aria-label="Permalink to “Module: eval”">​</a></h1><h2 id="contents" tabindex="-1">Contents <a class="header-anchor" href="#contents" aria-label="Permalink to “Contents”">​</a></h2><p><strong>Structs</strong></p><ul><li><a href="#basicevaluator"><code>BasicEvaluator</code></a> - Basic <code>RuleAcceptor</code> plugin for the <code>Eval</code> operation.</li><li><a href="#basicevaluatorcallback"><code>BasicEvaluatorCallback</code></a> - Concrete <code>EvaluatorCallback</code> backed by cloned rule and exec-control lists.</li><li><a href="#basicexeccontrol"><code>BasicExecControl</code></a> - A collection of [<code>ExecControl</code>] rules.</li><li><a href="#eval"><code>Eval</code></a> - Eval operation marker.</li><li><a href="#evalcontext"><code>EvalContext</code></a> - Execution context carried through an evaluation.</li><li><a href="#evallimits"><code>EvalLimits</code></a> - Resource limits for a single evaluation.</li><li><a href="#evalrequest"><code>EvalRequest</code></a> - Request passed to <code>Eval</code> behaviors.</li><li><a href="#handlerclause"><code>HandlerClause</code></a> - A handler clause in a <code>handle</code> expression.</li></ul><p><strong>Enums</strong></p><ul><li><a href="#controlflow"><code>ControlFlow</code></a> - Control flow outcome from an [<code>ExecControl::before_eval</code>] hook.</li><li><a href="#evalerror"><code>EvalError</code></a> - Errors specific to evaluation.</li></ul><p><strong>Traits</strong></p><ul><li><a href="#asyncfunction"><code>AsyncFunction</code></a> - A callable host function that supports async execution.</li><li><a href="#evalbehavior"><code>EvalBehavior</code></a> - Behavior trait for evaluating a specific <code>AstNode.kind</code>.</li><li><a href="#evaluatorcallback"><code>EvaluatorCallback</code></a> - Callback handle that lets an [<code>EvalContext</code>] recursively dispatch to the</li><li><a href="#execcontrol"><code>ExecControl</code></a> - Lightweight execution-control hook invoked before and after each dispatch.</li><li><a href="#exprevaluator"><code>ExprEvaluator</code></a> - String-expression evaluator callback for host functions that need to</li><li><a href="#function"><code>Function</code></a> - A callable host function, non-generic per ADR 0040.</li><li><a href="#module"><code>Module</code></a> - A named group of functions — the runtime-side analogue of a namespace.</li><li><a href="#modulelookup"><code>ModuleLookup</code></a> - Lookup handle for qualified function names, held by [<code>EvalContext</code>].</li><li><a href="#typesignature"><code>TypeSignature</code></a> - A function that exposes its type signature for typechecking (ADR-0083).</li><li><a href="#valuecallable"><code>ValueCallable</code></a> - A callable value evaluator — allows host functions to call arrow-values</li></ul><p><strong>Type Aliases</strong></p><ul><li><a href="#scope"><code>Scope</code></a> - A variable scope: a map of names to JSON values.</li></ul><hr><h2 id="handl-platform-eval-asyncfunction" tabindex="-1">handl_platform::eval::AsyncFunction <a class="header-anchor" href="#handl-platform-eval-asyncfunction" aria-label="Permalink to “handl_platform::eval::AsyncFunction”">​</a></h2><p><em>Trait</em></p><p>A callable host function that supports async execution.</p><p>This is the async counterpart of [<code>Function</code>], per ADR 0040&#39;s &quot;Async evaluation&quot; section. Functions that perform IO-bound work (HTTP, WebSocket, timers, sockets) implement this trait so they can be awaited from [<code>EvalContext::call_function_async</code>] without blocking the calling thread.</p><p>A type can implement <em>both</em> [<code>Function</code>] and [<code>AsyncFunction</code>]: the sync <code>call</code> is used by [<code>EvalContext::call_function</code>], and <code>call_async</code> is used by [<code>EvalContext::call_function_async</code>]. To make the async path visible to the lookup machinery, the [<code>Function::as_async</code>] override must return <code>Some(self)</code>.</p><p>The returned future is <code>Pin&lt;Box&lt;dyn Future + &#39;a&gt;&gt;</code> — single-threaded (consistent with [<code>EvalContext</code>]&#39;s <code>Rc</code>-based handles), no <code>Send</code> bound.</p><p><strong>Methods:</strong></p><ul><li><code>call_async</code>: Invoke the function asynchronously.</li></ul><h2 id="handl-platform-eval-basicevaluator" tabindex="-1">handl_platform::eval::BasicEvaluator <a class="header-anchor" href="#handl-platform-eval-basicevaluator" aria-label="Permalink to “handl_platform::eval::BasicEvaluator”">​</a></h2><p><em>Struct</em></p><p>Basic <code>RuleAcceptor</code> plugin for the <code>Eval</code> operation.</p><p>Holds registered <code>EvalBehavior</code> rules (keyed by <code>AstNode.kind</code> at dispatch time) and <code>ExecControl</code> hooks. <code>run</code> creates an <code>EvalContext</code> with a recursion handle, wraps it in an <code>EvalRequest</code>, and dispatches.</p><p><strong>Fields:</strong></p><ul><li><code>capabilities: Vec&lt;crate::CapabilityId&gt;</code> - Capabilities provided by this plugin.</li><li><code>rules: Vec&lt;std::sync::Arc&lt;dyn EvalBehavior&gt;&gt;</code> - Registered evaluation rules, keyed by <code>AstNode.kind</code>.</li><li><code>exec_controls: Vec&lt;std::sync::Arc&lt;dyn ExecControl&gt;&gt;</code> - Registered exec-control rules.</li><li><code>option_schemas: Vec&lt;crate::OptionSchema&gt;</code> - Option schemas contributed for the evaluator.</li></ul><p><strong>Methods:</strong></p><ul><li><code>fn new() -&gt; Self</code> - Create a new <code>BasicEvaluator</code> with no rules.</li><li><code>fn add_exec_control(self: &amp; mut Self, rule: Arc&lt;dyn ExecControl&gt;)</code> - Add an exec-control rule.</li><li><code>fn make_callback(self: &amp;Self) -&gt; Rc&lt;dyn EvaluatorCallback&gt;</code> - Create a recursion callback that can be wired into an [<code>EvalContext</code>]</li><li><code>fn resume(self: &amp;Self, ast: &amp;AstNode, context: EvalContext, ctx: &amp; mut PluginContext) -&gt; Result&lt;Value, PlatformError&gt;</code> - Resume evaluation from a yielded context.</li></ul><p><strong>Trait Implementations:</strong></p><ul><li><strong>Plugin</strong><ul><li><code>fn id(self: &amp;Self) -&gt; &amp;str</code></li><li><code>fn name(self: &amp;Self) -&gt; &amp;str</code></li><li><code>fn capabilities(self: &amp;Self) -&gt; &amp;[CapabilityId]</code></li><li><code>fn metadata(self: &amp;Self, capability: &amp;CapabilityId) -&gt; Option&lt;CapabilityMetadata&gt;</code></li><li><code>fn run(self: &amp;Self, request: &amp;CapabilityRequest, ctx: &amp; mut PluginContext) -&gt; Result&lt;CapabilityResponse, PlatformError&gt;</code></li></ul></li><li><strong>RuleAcceptor</strong><ul><li><code>fn accept(self: &amp; mut Self, rule: &lt;Self as &gt;::Rule) -&gt; Result&lt;(), PlatformError&gt;</code></li></ul></li><li><strong>Default</strong><ul><li><code>fn default() -&gt; Self</code></li></ul></li></ul><h2 id="handl-platform-eval-basicevaluatorcallback" tabindex="-1">handl_platform::eval::BasicEvaluatorCallback <a class="header-anchor" href="#handl-platform-eval-basicevaluatorcallback" aria-label="Permalink to “handl_platform::eval::BasicEvaluatorCallback”">​</a></h2><p><em>Struct</em></p><p>Concrete <code>EvaluatorCallback</code> backed by cloned rule and exec-control lists.</p><p>Created by <code>BasicEvaluator::run</code>; not intended to be constructed directly by consumer code.</p><p><strong>Fields:</strong></p><ul><li><code>rules: Vec&lt;std::sync::Arc&lt;dyn EvalBehavior&gt;&gt;</code> - Registered evaluation rules (cloned <code>Arc</code> pointers — cheap).</li><li><code>exec_controls: Vec&lt;std::sync::Arc&lt;dyn ExecControl&gt;&gt;</code> - Registered exec-control rules.</li></ul><p><strong>Trait Implementations:</strong></p><ul><li><strong>EvaluatorCallback</strong><ul><li><code>fn dispatch(self: &amp;Self, req: &amp; mut EvalRequest) -&gt; Result&lt;(), PlatformError&gt;</code></li></ul></li></ul><h2 id="handl-platform-eval-basicexeccontrol" tabindex="-1">handl_platform::eval::BasicExecControl <a class="header-anchor" href="#handl-platform-eval-basicexeccontrol" aria-label="Permalink to “handl_platform::eval::BasicExecControl”">​</a></h2><p><em>Struct</em></p><p>A collection of [<code>ExecControl</code>] rules.</p><p><code>BasicEvaluator</code> holds one of these internally. Kits can add rules via <code>BasicEvaluator::add_exec_control</code>.</p><p><strong>Fields:</strong></p><ul><li><code>rules: Vec&lt;std::sync::Arc&lt;dyn ExecControl&gt;&gt;</code> - Registered exec-control rules.</li></ul><p><strong>Methods:</strong></p><ul><li><code>fn new() -&gt; Self</code> - Create an empty <code>BasicExecControl</code>.</li><li><code>fn add(self: &amp; mut Self, rule: Arc&lt;dyn ExecControl&gt;)</code> - Add an exec-control rule.</li></ul><p><strong>Trait Implementations:</strong></p><ul><li><strong>Default</strong><ul><li><code>fn default() -&gt; Self</code></li></ul></li></ul><h2 id="handl-platform-eval-controlflow" tabindex="-1">handl_platform::eval::ControlFlow <a class="header-anchor" href="#handl-platform-eval-controlflow" aria-label="Permalink to “handl_platform::eval::ControlFlow”">​</a></h2><p><em>Enum</em></p><p>Control flow outcome from an [<code>ExecControl::before_eval</code>] hook.</p><p><code>Continue</code> lets dispatch proceed to the matching <code>Behavior&lt;Eval&gt;</code> rule. <code>Skip(value)</code> short-circuits dispatch: <code>value</code> becomes the result and no behavior rule runs (after-hooks still fire). This is how the cache plugin returns a cached result without re-executing.</p><p><strong>Variants:</strong></p><ul><li><code>Continue</code> - Proceed with normal dispatch.</li><li><code>Skip(serde_json::Value)</code> - Skip dispatch and use <code>value</code> as the result.</li></ul><p><strong>Methods:</strong></p><ul><li><code>fn continue_() -&gt; Self</code> - Convenience constructor for the <code>Continue</code> variant.</li></ul><p><strong>Trait Implementations:</strong></p><ul><li><strong>Clone</strong><ul><li><code>fn clone(self: &amp;Self) -&gt; Self</code></li></ul></li><li><strong>PartialEq</strong><ul><li><code>fn eq(self: &amp;Self, other: &amp;Self) -&gt; bool</code></li></ul></li><li><strong>Debug</strong><ul><li><code>fn fmt(self: &amp;Self, f: &amp; mut $crate::fmt::Formatter) -&gt; $crate::fmt::Result</code></li></ul></li></ul><h2 id="handl-platform-eval-eval" tabindex="-1">handl_platform::eval::Eval <a class="header-anchor" href="#handl-platform-eval-eval" aria-label="Permalink to “handl_platform::eval::Eval”">​</a></h2><p><em>Struct</em></p><p>Eval operation marker.</p><p><strong>Unit Struct</strong></p><p><strong>Traits:</strong> Operation, Copy</p><p><strong>Trait Implementations:</strong></p><ul><li><strong>Debug</strong><ul><li><code>fn fmt(self: &amp;Self, f: &amp; mut $crate::fmt::Formatter) -&gt; $crate::fmt::Result</code></li></ul></li><li><strong>Clone</strong><ul><li><code>fn clone(self: &amp;Self) -&gt; Self</code></li></ul></li></ul><h2 id="handl-platform-eval-evalbehavior" tabindex="-1">handl_platform::eval::EvalBehavior <a class="header-anchor" href="#handl-platform-eval-evalbehavior" aria-label="Permalink to “handl_platform::eval::EvalBehavior”">​</a></h2><p><em>Trait</em></p><p>Behavior trait for evaluating a specific <code>AstNode.kind</code>.</p><h2 id="handl-platform-eval-evalcontext" tabindex="-1">handl_platform::eval::EvalContext <a class="header-anchor" href="#handl-platform-eval-evalcontext" aria-label="Permalink to “handl_platform::eval::EvalContext”">​</a></h2><p><em>Struct</em></p><p>Execution context carried through an evaluation.</p><p>Holds a stack of variable scopes (JSON values), resource limits, a call counter, and an optional [<code>EvaluatorCallback</code>] handle for recursive evaluation. Rules access the context via <code>req.ctx</code> and call <code>req.ctx.eval(&amp;child)</code> to evaluate sub-expressions.</p><p>The context is the continuation: it captures all mutable state needed to resume or serialize an in-progress evaluation (see ADR 0040 — yield / resumability).</p><p><strong>Fields:</strong></p><ul><li><code>scopes: Vec&lt;Scope&gt;</code> - Stack of variable scopes, innermost last.</li><li><code>limits: EvalLimits</code> - Resource limits for this evaluation.</li><li><code>call_count: usize</code> - Number of dispatch calls made so far.</li><li><code>evaluator: Option&lt;std::rc::Rc&lt;dyn EvaluatorCallback&gt;&gt;</code> - Recursion handle — set by <code>BasicEvaluator::run</code>.</li><li><code>modules: Option&lt;std::rc::Rc&lt;dyn ModuleLookup&gt;&gt;</code> - Module/function lookup handle — set by the host before evaluation</li><li><code>expr_evaluator: Option&lt;std::rc::Rc&lt;dyn ExprEvaluator&gt;&gt;</code> - String-expression evaluator — set by the host so host functions</li><li><code>value_callable: Option&lt;std::rc::Rc&lt;dyn ValueCallable&gt;&gt;</code> - Value callable — set by the host so host functions can call</li><li><code>handlers: Vec&lt;Vec&lt;HandlerClause&gt;&gt;</code> - Stack of handler frames from enclosing <code>handle</code> expressions.</li></ul><p><strong>Methods:</strong></p><ul><li><code>fn new() -&gt; Self</code> - Create a new context with a single empty global scope and no</li><li><code>fn with_globals&lt;impl IntoIterator&lt;Item = (String, Value)&gt;&gt;(self: Self, vars: impl Trait) -&gt; Self</code> - Create a context seeded with the given top-level variables.</li><li><code>fn set_evaluator(self: &amp; mut Self, evaluator: Rc&lt;dyn EvaluatorCallback&gt;)</code> - Set the evaluator handle (for recursion).</li><li><code>fn set_modules(self: &amp; mut Self, modules: Rc&lt;dyn ModuleLookup&gt;)</code> - Set the module/function lookup handle (for <code>call_function</code>).</li><li><code>fn has_modules(self: &amp;Self) -&gt; bool</code> - Returns <code>true</code> if a module lookup handle is set.</li><li><code>fn set_expr_evaluator(self: &amp; mut Self, evaluator: Rc&lt;dyn ExprEvaluator&gt;)</code> - Set the string-expression evaluator handle.</li><li><code>fn set_value_callable(self: &amp; mut Self, callable: Rc&lt;dyn ValueCallable&gt;)</code> - Set the value callable handle (for <code>call_value</code>).</li><li><code>fn try_call_value(self: &amp; mut Self, callee: &amp;Value, args: &amp;[Value]) -&gt; Option&lt;Result&lt;Value, EvalError&gt;&gt;</code> - Call a callable value (e.g. arrow-value) with the given arguments.</li><li><code>fn eval_expr(self: &amp; mut Self, expr: &amp;str, vars: &amp;[(String, Value)]) -&gt; Result&lt;Value, EvalError&gt;</code> - Evaluate an expression string with the given variable bindings.</li><li><code>fn set_limits(self: &amp; mut Self, limits: EvalLimits)</code> - Set resource limits.</li><li><code>fn has_evaluator(self: &amp;Self) -&gt; bool</code> - Returns <code>true</code> if an evaluator handle is set (recursion is possible).</li><li><code>fn push_scope(self: &amp; mut Self)</code> - Push a new empty scope onto the stack.</li><li><code>fn pop_scope(self: &amp; mut Self) -&gt; Option&lt;Scope&gt;</code> - Pop the topmost scope. Returns <code>None</code> if only the global scope remains.</li><li><code>fn depth(self: &amp;Self) -&gt; usize</code> - Current scope depth (global scope is depth 1).</li><li><code>fn define&lt;impl Into&lt;String&gt;&gt;(self: &amp; mut Self, name: impl Trait, value: Value)</code> - Define (or overwrite) a variable in the current (topmost) scope.</li><li><code>fn get(self: &amp;Self, name: &amp;str) -&gt; Result&lt;Value, EvalError&gt;</code> - Look up a variable by name, searching from the innermost scope outward.</li><li><code>fn lookup(self: &amp;Self, name: &amp;str) -&gt; Option&lt;&amp;Value&gt;</code> - Returns a reference to the variable if found in any scope.</li><li><code>fn collect_vars(self: &amp;Self) -&gt; HashMap&lt;String, Value&gt;</code> - Collect all variables from all scopes into a map.</li><li><code>fn limits(self: &amp;Self) -&gt; &amp;EvalLimits</code> - Returns the configured limits.</li><li><code>fn call_count(self: &amp;Self) -&gt; usize</code> - Returns the number of dispatch calls made so far.</li><li><code>fn bump_call_count(self: &amp; mut Self) -&gt; usize</code> - Increment the call counter and return the new count.</li><li><code>fn increment_call_count(self: &amp; mut Self) -&gt; Result&lt;(), PlatformError&gt;</code> - Increment the call counter. Returns an error if <code>max_calls</code> is exceeded.</li><li><code>fn check_depth(self: &amp;Self) -&gt; Result&lt;(), PlatformError&gt;</code> - Check whether pushing another scope would exceed <code>max_depth</code>.</li><li><code>fn eval(self: &amp; mut Self, ast: &amp;AstNode) -&gt; Result&lt;Value, PlatformError&gt;</code> - Evaluate a child AST node by dispatching through the evaluator handle.</li><li><code>fn call_function(self: &amp; mut Self, name: &amp;str, args: &amp;[Value]) -&gt; Result&lt;Value, EvalError&gt;</code> - Call a registered host function by qualified name.</li><li><code>fn eval_async&lt;&#39;a&gt;(self: &amp;&#39;a mut Self, node: &amp;&#39;a AstNode) -&gt; Pin&lt;Box&lt;dyn Future&gt;&gt;</code> - Asynchronously evaluate a child AST node.</li><li><code>fn call_function_async&lt;&#39;a&gt;(self: &amp;&#39;a mut Self, name: &amp;&#39;a str, args: &amp;&#39;a [Value]) -&gt; Pin&lt;Box&lt;dyn Future&gt;&gt;</code> - Asynchronously call a registered host function by qualified name.</li><li><code>fn yield_now(self: Self) -&gt; EvalError</code> - Yield execution, capturing the current context for later resumption.</li><li><code>fn to_json(self: &amp;Self) -&gt; Result&lt;serde_json::Value, serde_json::Error&gt;</code> - Serialize the context for cross-machine resumability.</li><li><code>fn from_json(json: &amp;serde_json::Value) -&gt; Result&lt;Self, serde_json::Error&gt;</code> - Deserialize a context for resumption.</li><li><code>fn push_handlers(self: &amp; mut Self, handlers: Vec&lt;HandlerClause&gt;)</code> - Push a handler frame (a list of [<code>HandlerClause</code>]s) onto the handler</li><li><code>fn pop_handlers(self: &amp; mut Self) -&gt; Option&lt;Vec&lt;HandlerClause&gt;&gt;</code> - Pop the topmost handler frame.</li><li><code>fn find_handler(self: &amp;Self, operation: &amp;str) -&gt; Option&lt;&amp;HandlerClause&gt;</code> - Find the handler clause matching <code>operation</code>, searching from the</li><li><code>fn has_handler(self: &amp;Self, operation: &amp;str) -&gt; bool</code> - Returns <code>true</code> if any handler clause matches <code>operation</code>.</li><li><code>fn handler_depth(self: &amp;Self) -&gt; usize</code> - Returns the number of handler frames on the stack.</li></ul><p><strong>Trait Implementations:</strong></p><ul><li><strong>Default</strong><ul><li><code>fn default() -&gt; Self</code></li></ul></li><li><strong>PartialEq</strong><ul><li><code>fn eq(self: &amp;Self, other: &amp;Self) -&gt; bool</code> - Compares only the serializable state (<code>scopes</code>, <code>limits</code>,</li></ul></li><li><strong>Deserialize</strong><ul><li><code>fn deserialize&lt;__D&gt;(__deserializer: __D) -&gt; _serde::__private229::Result&lt;Self, &lt;__D as &gt;::Error&gt;</code></li></ul></li><li><strong>Clone</strong><ul><li><code>fn clone(self: &amp;Self) -&gt; Self</code></li></ul></li><li><strong>Serialize</strong><ul><li><code>fn serialize&lt;__S&gt;(self: &amp;Self, __serializer: __S) -&gt; _serde::__private229::Result&lt;&lt;__S as &gt;::Ok, &lt;__S as &gt;::Error&gt;</code></li></ul></li><li><strong>Debug</strong><ul><li><code>fn fmt(self: &amp;Self, f: &amp; mut std::fmt::Formatter) -&gt; std::fmt::Result</code></li></ul></li></ul><h2 id="handl-platform-eval-evalerror" tabindex="-1">handl_platform::eval::EvalError <a class="header-anchor" href="#handl-platform-eval-evalerror" aria-label="Permalink to “handl_platform::eval::EvalError”">​</a></h2><p><em>Enum</em></p><p>Errors specific to evaluation.</p><p>These are raised by <code>EvalBehavior</code> rules and exec-control hooks during tree-walking evaluation. They can be converted into [<code>PlatformError</code>] via the <code>From</code> impl so that <code>Behavior&lt;Eval&gt;::apply</code> can return them seamlessly.</p><p><strong>Variants:</strong></p><ul><li><code>Yield{ context: EvalContext }</code> - Execution yielded, capturing the current [<code>EvalContext</code>] for later</li><li><code>UnknownFunction(String)</code> - A function was called that is not registered in any module.</li><li><code>TypeMismatch(String)</code> - A value did not match the expected type.</li><li><code>UnknownVariable(String)</code> - A variable was referenced that is not bound in any scope.</li><li><code>ResourceLimit(String)</code> - A resource limit (depth, calls, etc.) was exceeded.</li><li><code>Other(String)</code> - A generic evaluation error.</li></ul><p><strong>Traits:</strong> Error</p><p><strong>Trait Implementations:</strong></p><ul><li><strong>Clone</strong><ul><li><code>fn clone(self: &amp;Self) -&gt; Self</code></li></ul></li><li><strong>PartialEq</strong><ul><li><code>fn eq(self: &amp;Self, other: &amp;Self) -&gt; bool</code></li></ul></li><li><strong>Debug</strong><ul><li><code>fn fmt(self: &amp;Self, f: &amp; mut $crate::fmt::Formatter) -&gt; $crate::fmt::Result</code></li></ul></li><li><strong>Display</strong><ul><li><code>fn fmt(self: &amp;Self, __formatter: &amp; mut ::core::fmt::Formatter) -&gt; ::core::fmt::Result</code></li></ul></li></ul><h2 id="handl-platform-eval-evallimits" tabindex="-1">handl_platform::eval::EvalLimits <a class="header-anchor" href="#handl-platform-eval-evallimits" aria-label="Permalink to “handl_platform::eval::EvalLimits”">​</a></h2><p><em>Struct</em></p><p>Resource limits for a single evaluation.</p><p>When set, <code>BasicEvaluator</code> checks <code>max_depth</code> before pushing a new scope and <code>max_calls</code> before each dispatch, returning [<code>EvalError::ResourceLimit</code>] if the limit would be exceeded.</p><p><strong>Fields:</strong></p><ul><li><code>max_depth: Option&lt;usize&gt;</code> - Maximum scope depth (number of nested scopes).</li><li><code>max_calls: Option&lt;usize&gt;</code> - Maximum number of dispatch calls.</li></ul><p><strong>Trait Implementations:</strong></p><ul><li><strong>Clone</strong><ul><li><code>fn clone(self: &amp;Self) -&gt; Self</code></li></ul></li><li><strong>Debug</strong><ul><li><code>fn fmt(self: &amp;Self, f: &amp; mut $crate::fmt::Formatter) -&gt; $crate::fmt::Result</code></li></ul></li><li><strong>Deserialize</strong><ul><li><code>fn deserialize&lt;__D&gt;(__deserializer: __D) -&gt; _serde::__private229::Result&lt;Self, &lt;__D as &gt;::Error&gt;</code></li></ul></li><li><strong>Serialize</strong><ul><li><code>fn serialize&lt;__S&gt;(self: &amp;Self, __serializer: __S) -&gt; _serde::__private229::Result&lt;&lt;__S as &gt;::Ok, &lt;__S as &gt;::Error&gt;</code></li></ul></li><li><strong>Default</strong><ul><li><code>fn default() -&gt; Self</code></li></ul></li><li><strong>PartialEq</strong><ul><li><code>fn eq(self: &amp;Self, other: &amp;Self) -&gt; bool</code></li></ul></li></ul><h2 id="handl-platform-eval-evalrequest" tabindex="-1">handl_platform::eval::EvalRequest <a class="header-anchor" href="#handl-platform-eval-evalrequest" aria-label="Permalink to “handl_platform::eval::EvalRequest”">​</a></h2><p><em>Struct</em></p><p>Request passed to <code>Eval</code> behaviors.</p><p>Carries the AST node to evaluate, an [<code>EvalContext</code>] with variable scopes and a recursion handle, resolved options, and an optional result slot. <code>Behavior&lt;Eval&gt;::apply(&amp;self, req: &amp;mut EvalRequest)</code> reads <code>req.ast</code> and <code>req.ctx</code>, recurses via <code>req.ctx.eval(&amp;child)</code>, and writes <code>req.result</code>.</p><p><strong>Fields:</strong></p><ul><li><code>ast: crate::AstNode</code> - The AST node to evaluate.</li><li><code>ctx: EvalContext</code> - Execution context (scopes, limits, recursion handle).</li><li><code>options: crate::ResolvedOptions</code> - Resolved evaluator options.</li><li><code>result: Option&lt;serde_json::Value&gt;</code> - Optional result produced by a behavior.</li></ul><p><strong>Trait Implementations:</strong></p><ul><li><strong>Debug</strong><ul><li><code>fn fmt(self: &amp;Self, f: &amp; mut std::fmt::Formatter) -&gt; std::fmt::Result</code></li></ul></li><li><strong>Clone</strong><ul><li><code>fn clone(self: &amp;Self) -&gt; Self</code></li></ul></li></ul><h2 id="handl-platform-eval-evaluatorcallback" tabindex="-1">handl_platform::eval::EvaluatorCallback <a class="header-anchor" href="#handl-platform-eval-evaluatorcallback" aria-label="Permalink to “handl_platform::eval::EvaluatorCallback”">​</a></h2><p><em>Trait</em></p><p>Callback handle that lets an [<code>EvalContext</code>] recursively dispatch to the owning <code>BasicEvaluator</code>.</p><p><code>BasicEvaluator</code> creates an <code>Rc&lt;dyn EvaluatorCallback&gt;</code> at the start of <code>run</code> and stores it inside the <code>EvalContext</code>. When a rule needs to evaluate a child AST node it calls <code>ctx.eval(&amp;child)</code>, which delegates to <code>EvaluatorCallback::dispatch</code>.</p><p>The trait is <code>&#39;static</code> (no <code>Send</code>/<code>Sync</code> bound) because evaluation is single-threaded and synchronous.</p><p><strong>Methods:</strong></p><ul><li><code>dispatch</code>: Dispatch <code>req</code> to the matching <code>Behavior&lt;Eval&gt;</code> rule, calling</li></ul><h2 id="handl-platform-eval-execcontrol" tabindex="-1">handl_platform::eval::ExecControl <a class="header-anchor" href="#handl-platform-eval-execcontrol" aria-label="Permalink to “handl_platform::eval::ExecControl”">​</a></h2><p><em>Trait</em></p><p>Lightweight execution-control hook invoked before and after each dispatch.</p><p>Exec-control concerns (limits, tracing, caching, sandboxing) are handled by this two-hook trait rather than a full middleware wrapping trait. Eval is the only operation with cross-cutting execution concerns, so this one deviation from the uniform <code>Behavior</code> pattern is justified (see ADR 0040).</p><p><code>BasicEvaluator</code> calls all registered <code>ExecControl</code> rules before and after each dispatch. When none are loaded the overhead is a zero-length slice iteration.</p><p><code>before_eval</code> receives a <code>&amp;mut AstNode</code> so that rewriting rules (e.g. the map plugin) can mutate the node in place before dispatch. Returning [<code>ControlFlow::Skip</code>] short-circuits dispatch with a precomputed result (used by the cache plugin).</p><p><strong>Methods:</strong></p><ul><li><code>before_eval</code>: Called before dispatching to the matching <code>Behavior&lt;Eval&gt;</code> rule.</li><li><code>after_eval</code>: Called after a successful dispatch (or a short-circuited skip), with</li></ul><h2 id="handl-platform-eval-exprevaluator" tabindex="-1">handl_platform::eval::ExprEvaluator <a class="header-anchor" href="#handl-platform-eval-exprevaluator" aria-label="Permalink to “handl_platform::eval::ExprEvaluator”">​</a></h2><p><em>Trait</em></p><p>String-expression evaluator callback for host functions that need to evaluate expression strings (e.g. <code>FunctionValue.body</code>) with variable bindings.</p><p>This is the ADR 0040 replacement for the old <code>Eval&lt;V&gt;</code> trait from <code>plugin-vm</code>. The concrete implementation is provided by the host (e.g. <code>kit-canonical</code>) and set on <code>EvalContext</code> via [<code>EvalContext::set_expr_evaluator</code>].</p><p><strong>Methods:</strong></p><ul><li><code>eval_expr</code>: Evaluate an expression string with the given variable bindings.</li></ul><h2 id="handl-platform-eval-function" tabindex="-1">handl_platform::eval::Function <a class="header-anchor" href="#handl-platform-eval-function" aria-label="Permalink to “handl_platform::eval::Function”">​</a></h2><p><em>Trait</em></p><p>A callable host function, non-generic per ADR 0040.</p><p>Functions live in modules and are looked up by qualified name (e.g. <code>math.add</code>) via [<code>ModuleLookup</code>]. The <code>call</code> method receives the already-evaluated JSON arguments and a mutable [<code>EvalContext</code>] so the function can itself recurse (<code>ctx.eval</code>, <code>ctx.call_function</code>) or inspect variable bindings. There is no <code>V</code> genericity — values are <code>serde_json::Value</code>.</p><p><strong>Methods:</strong></p><ul><li><code>call</code>: Invoke the function.</li><li><code>as_async</code>: Downcast this function to an [<code>AsyncFunction</code>] if it supports async</li><li><code>as_type_signature</code>: Downcast this function to a [<code>TypeSignature</code>] if it exposes a type</li></ul><h2 id="handl-platform-eval-handlerclause" tabindex="-1">handl_platform::eval::HandlerClause <a class="header-anchor" href="#handl-platform-eval-handlerclause" aria-label="Permalink to “handl_platform::eval::HandlerClause”">​</a></h2><p><em>Struct</em></p><p>A handler clause in a <code>handle</code> expression.</p><p>When an operation (effect) is performed inside a <code>handle</code> expression, the matching handler clause runs. If the handler resumes (by calling the continuation), the computation continues from where the effect was performed.</p><p>See ADR 0040 — Continuation / yield / resumability.</p><p><strong>Fields:</strong></p><ul><li><code>operation: String</code> - The operation name this clause matches (e.g. <code>&quot;fetch&quot;</code>).</li><li><code>params: Vec&lt;String&gt;</code> - Parameter names bound when the handler fires (bound to the</li><li><code>resume_name: String</code> - The continuation name — bound to a resume function in the handler&#39;s</li><li><code>body: crate::AstNode</code> - The handler body AST. Evaluated when the handler fires; its result</li></ul><p><strong>Trait Implementations:</strong></p><ul><li><strong>Serialize</strong><ul><li><code>fn serialize&lt;__S&gt;(self: &amp;Self, __serializer: __S) -&gt; _serde::__private229::Result&lt;&lt;__S as &gt;::Ok, &lt;__S as &gt;::Error&gt;</code></li></ul></li><li><strong>Clone</strong><ul><li><code>fn clone(self: &amp;Self) -&gt; Self</code></li></ul></li><li><strong>Debug</strong><ul><li><code>fn fmt(self: &amp;Self, f: &amp; mut $crate::fmt::Formatter) -&gt; $crate::fmt::Result</code></li></ul></li><li><strong>Deserialize</strong><ul><li><code>fn deserialize&lt;__D&gt;(__deserializer: __D) -&gt; _serde::__private229::Result&lt;Self, &lt;__D as &gt;::Error&gt;</code></li></ul></li><li><strong>PartialEq</strong><ul><li><code>fn eq(self: &amp;Self, other: &amp;Self) -&gt; bool</code></li></ul></li></ul><h2 id="handl-platform-eval-module" tabindex="-1">handl_platform::eval::Module <a class="header-anchor" href="#handl-platform-eval-module" aria-label="Permalink to “handl_platform::eval::Module”">​</a></h2><p><em>Trait</em></p><p>A named group of functions — the runtime-side analogue of a namespace.</p><p>A module provides a namespace for host functions. The module name becomes the first segment of a qualified function name — e.g. a module named <code>&quot;math&quot;</code> providing a function <code>&quot;add&quot;</code> is callable as <code>math.add(1, 2)</code>. Which modules exist is a runtime host decision, not a language-level feature.</p><p><strong>Methods:</strong></p><ul><li><code>name</code>: The module name — the namespace prefix for qualified calls.</li><li><code>function</code>: Resolve a function name (without the module prefix) to a callable.</li><li><code>functions</code>: Enumerate all <code>(name, function)</code> pairs in this module.</li><li><code>value_names</code>: Enumerate the names this module exports as plain (non-callable)</li><li><code>value</code>: Resolve a value export (without the module prefix) to its evaluated</li><li><code>bindings_tagged</code>: The module&#39;s export record as a shared [<code>TaggedValue</code>] — the</li></ul><h2 id="handl-platform-eval-modulelookup" tabindex="-1">handl_platform::eval::ModuleLookup <a class="header-anchor" href="#handl-platform-eval-modulelookup" aria-label="Permalink to “handl_platform::eval::ModuleLookup”">​</a></h2><p><em>Trait</em></p><p>Lookup handle for qualified function names, held by [<code>EvalContext</code>].</p><p><code>EvalContext</code> cannot depend on <code>plugin-module</code> (where the concrete <a href="./../handl_plugin_module/struct.ModuleRegistry.html"><code>ModuleRegistry</code></a> lives), so it holds an <code>Option&lt;Rc&lt;dyn ModuleLookup&gt;&gt;</code>. The concrete <code>ModuleRegistry</code> in <code>plugin-module</code> implements this trait. When no registry is wired up, <code>call_function</code> returns [<code>EvalError::UnknownFunction</code>].</p><p><strong>Methods:</strong></p><ul><li><code>lookup</code>: Resolve a qualified name (e.g. <code>math.add</code>) or flat name (e.g. <code>add</code>)</li><li><code>lookup_type_signature</code>: Look up the type signature of a qualified op name (ADR-0083).</li><li><code>lookup_module_exports</code>: Enumerate a module&#39;s exported names for signature-record</li></ul><h2 id="handl-platform-eval-scope" tabindex="-1">handl_platform::eval::Scope <a class="header-anchor" href="#handl-platform-eval-scope" aria-label="Permalink to “handl_platform::eval::Scope”">​</a></h2><p><em>Type Alias</em>: <code>std::collections::HashMap&lt;String, serde_json::Value&gt;</code></p><p>A variable scope: a map of names to JSON values.</p><h2 id="handl-platform-eval-typesignature" tabindex="-1">handl_platform::eval::TypeSignature <a class="header-anchor" href="#handl-platform-eval-typesignature" aria-label="Permalink to “handl_platform::eval::TypeSignature”">​</a></h2><p><em>Trait</em></p><p>A function that exposes its type signature for typechecking (ADR-0083).</p><p><code>Function</code> impls that represent declared <code>op</code>s (with <code>op &quot;x&quot; : T -&gt; T</code> signatures) implement this trait so the typechecker can look up the op&#39;s type without executing it. The signature is a type value (ADR-0032).</p><p><strong>Methods:</strong></p><ul><li><code>type_signature</code>: The op&#39;s type signature as a type value (e.g. a <code>type.function</code> value).</li></ul><h2 id="handl-platform-eval-valuecallable" tabindex="-1">handl_platform::eval::ValueCallable <a class="header-anchor" href="#handl-platform-eval-valuecallable" aria-label="Permalink to “handl_platform::eval::ValueCallable”">​</a></h2><p><em>Trait</em></p><p>A callable value evaluator — allows host functions to call arrow-values (first-class function values from the tree-walk engine) by passing the value and arguments through the eval engine.</p><p>This is the bridge between <code>fn.*</code> combinators (which receive arrow-values as arguments) and the tree-walk engine (which knows how to invoke them).</p><p><strong>Methods:</strong></p><ul><li><code>call_value</code>: Call a callable value (e.g. arrow-value <code>{__arrow__: true, ...}</code>) with</li></ul>`,167)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};